using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "SoulHeatBasedAction", menuName = "Data/Battle/Battle Actions/Sothis/SoulHeatBased Action")]
public class SoulHeatBasedAction : BattleAction
{
	[Header("Soul Heat")]
	[SerializeField]
	private bool resetSoulHeatAfterUse;

	[SerializeField]
	[HideIf("isEvilSoulHeatBased")]
	private SoulHeat soulHeat;

	[Header("Battle Action")]
	[SerializeField]
	private BattleAction battleAction;

	[Header("Evil Soul Heat")]
	[SerializeField]
	private bool isEvilSoulHeatBased;

	[SerializeField]
	[ShowIf("isEvilSoulHeatBased")]
	private EvilSoulHeat evilSoulHeat;

	public BattleAction BattleAction => battleAction;

	public bool IsEvilSoulHeatBased => isEvilSoulHeatBased;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		return soulHeat.SoulHeatCounter > 0;
	}

	public int GetAmount(int amount)
	{
		return (isEvilSoulHeatBased ? evilSoulHeat.EvilSoulHeatCounter : soulHeat.SoulHeatCounter) * amount;
	}

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		PlaySFX();
		SpawnVFX(GetVFXOwnerPosition(target), 3f);
		battleAction.CastTargetAmount(target, GetAmount(amount), source);
		if (resetSoulHeatAfterUse)
		{
			if (isEvilSoulHeatBased)
			{
				evilSoulHeat.ResetSoulHeat();
			}
			else
			{
				soulHeat.ResetSoulHeat();
			}
		}
	}

	public override void CastTarget(GameObject target, GameObject source)
	{
		CastTargetAmount(target, 1, source);
	}
}
